<script setup>
import { ref, computed, nextTick, onBeforeUnmount, watch } from 'vue'
import * as echarts from 'echarts'
import Sweep from './Sweep.vue'
import HouseholdWizard from './HouseholdWizard.vue'
import { cloneCase, shaftRun, makeupCase, parseCase, encodeCase, parameterSources, exampleNoise } from './cases'
import { runCalculation } from './transport'

const active = ref('ventilation'), mode = ref('service'), inverseResults = ref([])
const cases = ref(Object.fromEntries(['ventilation','dwelling','shaft','commissioning'].map(k => [k, cloneCase(k)])))
const result = ref(null), error = ref(''), busy = ref(false), editor = ref(''), chartEl = ref(null), sourceRows = ref([])
let chart
const current = computed(() => cases.value[active.value])
const input = computed(() => active.value === 'shaft' ? current.value.input.shaft : current.value.input)
const sourceText = '参数来源：用户输入或假设，需作者确认；通用参数及其出处以计算结果为准。'
const scenarioNames={no_makeup:'无补风',interlock:'联锁',opening:'起居室自然补风',opening_kitchen:'厨房自然补风',mechanical_living:'起居室机械补风',mechanical_kitchen:'厨房机械补风'}
const roomNames={living:'起居室',kitchen:'厨房',bath:'卫生间',bed1:'卧室一',bed2:'卧室二',bed3:'卧室三',bed4:'卧室四'}
function select(k) { active.value=k; result.value=null; inverseResults.value=[]; error.value=''; editor.value=['sweep','household'].includes(k)?'':encodeCase(cases.value[k], 'json') }
watch(mode, () => { result.value=null; inverseResults.value=[]; error.value='' })
select('ventilation')
function updateEditor() { editor.value=encodeCase(current.value,'json') }
function selectVentilation(kind) { cases.value.ventilation=cloneCase(kind); result.value=null; error.value=''; updateEditor() }
function toggleNoise(value) { if(value) current.value.input.noise=exampleNoise(); else delete current.value.input.noise; updateEditor() }
function applyEditor() { try { cases.value[active.value]=parseCase(editor.value); error.value='' } catch(e) { error.value=e.message } }
function downloadBlob(blob,name) { const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),1000) }
function exportCase(fmt) { downloadBlob(new Blob([encodeCase(current.value,fmt)],{type:'text/plain'}),`算例.${fmt}`) }
async function importCase(event) { try { cases.value[active.value]=parseCase(await event.target.files[0].text()); updateEditor(); error.value='' } catch(e){error.value=e.message} }
async function calculateInverse() {
  busy.value=true; error.value=''; inverseResults.value=[]
  const chosenMode=mode.value, submitted=JSON.parse(JSON.stringify(current.value.input))
  try {
    const rows=[]
    for (const n50 of submitted.n50_per_h) rows.push({n50, result:await runCalculation(makeupCase(submitted,n50),chosenMode)})
    if (mode.value===chosenMode && active.value==='dwelling') inverseResults.value=rows
  } catch(e) { error.value=e.message } finally { busy.value=false }
}
async function calculate() {
  busy.value=true; error.value=''; result.value=null
  try {
    const kind=active.value, chosenMode=mode.value, submitted=JSON.parse(JSON.stringify(current.value))
    const payload=kind==='shaft' ? shaftRun(submitted) : submitted
    const x=await runCalculation(payload, chosenMode)
    if(active.value!==kind || mode.value!==chosenMode) return
    sourceRows.value=parameterSources(kind,submitted)
    result.value=x
    await nextTick()
    if(active.value==='shaft' && chartEl.value) { chart?.dispose(); chart=echarts.init(chartEl.value); chart.setOption({title:{text:'逐层排风量'},tooltip:{},xAxis:{type:'category',data:x.floors.map(f=>`${f.floor}层`)},yAxis:{name:'m³/h'},series:[{type:'bar',data:x.floors.map(f=>f.exhaust_m3_s*3600)}]}) }
  } catch(e) { error.value=e.message } finally { busy.value=false }
}
async function downloadReport(kind) { try { if(mode.value==='browser') throw new Error('浏览器模式不支持 DOCX，请切换本机服务'); const payload=kind==='shaft'?cases.value.shaft:kind==='commissioning'?cases.value.commissioning:(active.value==='ventilation'||active.value==='dwelling'?current.value:cases.value.ventilation); const r=await fetch(`/report?type=${kind}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}); if(!r.ok)throw new Error(JSON.stringify((await r.json()).detail));downloadBlob(await r.blob(),'通风计算报告.docx') } catch(e){error.value=e.message} }
onBeforeUnmount(()=>chart?.dispose())
</script>
<template>
<main><header><h1>住宅通风设计与校核</h1><p>示例参数仅用于演示，请按实际项目核实；计算不替代现场检测与安全评估。</p><label>计算模式 <el-radio-group v-model="mode"><el-radio-button value="service">本机服务</el-radio-button><el-radio-button value="browser">浏览器本地计算</el-radio-button></el-radio-group></label><p v-if="mode==='browser'">浏览器运行时需单独准备，安装包不含运行时；<a href="/browser-runtime-help" target="_blank" rel="noopener">查看准备说明</a>。浏览器计算输入不发送至服务；DOCX、参数扫描、CFD 和外部对照暂不支持，请切换本机服务或命令行。</p></header>
<el-tabs :model-value="active" @tab-change="select"><el-tab-pane label="一户校核" name="household"/><el-tab-pane label="全户新风量设计" name="ventilation"/><el-tab-pane label="户内压差与补风" name="dwelling"/><el-tab-pane label="高层竖井" name="shaft"/><el-tab-pane label="报告下载" name="commissioning"/><el-tab-pane label="参数扫描" name="sweep"/></el-tabs>
<HouseholdWizard v-if="active==='household'" :mode="mode"/><Sweep v-if="active==='sweep' && mode==='service'"/><el-alert v-if="active==='sweep' && mode==='browser'" title="浏览器模式不支持参数扫描，请切换本机服务或命令行。" type="info" :closable="false"/>
<el-alert v-if="error" type="error" :title="error" :closable="false" show-icon/>
<el-card v-if="active==='ventilation'"><template #header>示例算例</template><el-select :model-value="current.module==='co2'?'single':'ventilation'" @update:model-value="selectVentilation"><el-option label="二氧化碳法" value="single"/><el-option label="全户新风量" value="ventilation"/></el-select></el-card>
<el-card v-if="active==='ventilation' && current.module==='co2'"><template #header>二氧化碳法参数</template><div class="grid"><label>人数（人）<el-input-number v-model="input.occupants" :min="1" @change="updateEditor"/></label><label>人均排放（L/h）<el-input-number v-model="input.co2_l_h_person" :min="0" @change="updateEditor"/></label><label>室外浓度（ppm）<el-input-number v-model="input.co2_outdoor_ppm" :min="0" @change="updateEditor"/></label><label>室内限值（ppm）<el-input-number v-model="input.co2_limit_ppm" :min="1" @change="updateEditor"/></label></div></el-card>
<el-card v-if="active==='ventilation' && current.module==='ventrate'"><template #header>全户参数</template><div class="grid"><label>居住面积（m²）<el-input-number v-model="input.area_m2" :min="1" @change="updateEditor"/></label><label>建筑面积（m²）<el-input-number v-model="input.floor_area_m2" :min="1" @change="updateEditor"/></label><label>净高（m）<el-input-number v-model="input.height_m" :min="1" :step="0.1" @change="updateEditor"/></label><label>设计人数（人）<el-input-number v-model="input.occupants" :min="1" @change="updateEditor"/></label><label>风量附加率<el-input-number v-model="input.allowance" :min="0.05" :max="0.1" :step="0.01" @change="updateEditor"/></label></div><h3>卧室</h3><div v-for="(room,i) in input.bedrooms" :key="i" class="grid"><span>卧室 {{i+1}}</span><label>面积（m²）<el-input-number v-model="room.area_m2" :min="1" @change="updateEditor"/></label><label>净高（m）<el-input-number v-model="room.height_m" :min="1" :step="0.1" @change="updateEditor"/></label><label>人数<el-input-number v-model="room.occupants" :min="0" @change="updateEditor"/></label></div><h3>起居室</h3><div class="grid"><label>面积（m²）<el-input-number v-model="input.living.area_m2" :min="1" @change="updateEditor"/></label><label>净高（m）<el-input-number v-model="input.living.height_m" :min="1" :step="0.1" @change="updateEditor"/></label></div><p>装修材料甲醛参数可在下方算例编辑区调整。</p></el-card>
<el-card v-if="active==='ventilation' && current.module==='ventrate'"><template #header>卧室噪声校核（可选）</template><label>启用噪声初算 <el-switch :model-value="!!input.noise" @change="toggleNoise"/></label><template v-if="input.noise"><p>各项初始声学参数是假设，需作者确认；风机声功率、管道衰减及再生声须以检测数据替换。更多参数可在算例编辑区修改。</p><div class="grid"><label v-for="(frequency,i) in [63,125,250,500,1000,2000,4000,8000]" :key="frequency">{{frequency}} Hz 声功率级（dB）<el-input-number v-model="input.noise.fan_power_db[i]" :min="0" :max="150" @change="updateEditor"/></label><label>距风口（m）<el-input-number v-model="input.noise.distance_m" :min="0.1" :step="0.1" @change="updateEditor"/></label><label>房间常数（m²）<el-input-number v-model="input.noise.room_constant_m2" :min="1" @change="updateEditor"/></label></div></template></el-card>
<el-card v-if="active==='dwelling'"><template #header>户内设备和补风</template><div class="grid"><label>卧室数<el-input-number v-model="input.bedrooms" :min="2" :max="4" @change="updateEditor"/></label><label>住宅体积（m³）<el-input-number v-model="input.volume_m3" :min="1" @change="updateEditor"/></label><label>油烟机风量（m³/h）<el-input-number v-model="input.hood_m3_h" :min="0" @change="updateEditor"/></label><label>新风送风量（m³/h）<el-input-number v-model="input.fresh_supply_m3_h" :min="0" @change="updateEditor"/></label><label>新风排风量（m³/h）<el-input-number v-model="input.fresh_exhaust_m3_h" :min="0" @change="updateEditor"/></label><label>补风口面积（m²）<el-input-number v-model="input.opening_area_m2" :min="0" :step="0.005" @change="updateEditor"/></label><label>机械补风（m³/h）<el-input-number v-model="input.mechanical_makeup_m3_h" :min="0" @change="updateEditor"/></label></div><div class="grid"><label v-for="(n,i) in input.n50_per_h" :key="i">气密性 n50（次/h）<el-input-number v-model="input.n50_per_h[i]" :min="0.01" :step="0.1" @change="updateEditor"/></label><label>厨房方式<el-select v-model="input.kitchen_open" @change="updateEditor"><el-option label="开敞式" :value="true"/><el-option label="封闭式" :value="false"/></el-select></label><label>油烟机位置<el-select v-model="input.hood_room" @change="updateEditor"><el-option label="厨房" value="kitchen"/><el-option label="起居室" value="living"/></el-select></label><label>新风送风位置<el-select v-model="input.supply_room" @change="updateEditor"><el-option label="起居室" value="living"/><el-option label="厨房" value="kitchen"/><el-option label="卧室一" value="bed1"/></el-select></label><label>提示阈值（Pa）<el-input-number v-model="input.threshold_pa" :min="1" @change="updateEditor"/></label></div><p>可同时比较自然补风、机械补风及联锁方案；15 Pa 仅为示例提示值，不是安全限值。</p></el-card>
<el-card v-if="active==='shaft'"><template #header>共用竖井参数</template><div class="grid"><label>楼层数<el-input-number v-model="input.floors" :min="1" :max="100" @change="updateEditor"/></label><label>截面宽（m）<el-input-number :model-value="input.width ?? 0.5" :min="0.1" :step="0.1" @update:model-value="input.width=$event;updateEditor()"/></label><label>截面深（m）<el-input-number :model-value="input.depth ?? 0.4" :min="0.1" :step="0.1" @update:model-value="input.depth=$event;updateEditor()"/></label><label>使用率<el-input-number v-model="input.fraction" :min="0.01" :max="1" :step="0.1" @change="updateEditor"/></label><label>分布<el-select v-model="input.distribution" @change="updateEditor"><el-option label="均匀" value="uniform"/><el-option label="低层" value="lower"/><el-option label="高层" value="upper"/><el-option label="随机" value="random"/></el-select></label><label>风机类型<el-select :model-value="input.fan_kind ?? 'ordinary'" @update:model-value="input.fan_kind=$event;updateEditor()"><el-option label="普通" value="ordinary"/><el-option label="标准" value="common"/><el-option label="高静压" value="high"/></el-select></label><label>止回阀等级<el-select :model-value="input.valve_class ?? 'medium'" @update:model-value="input.valve_class=$event;updateEditor()"><el-option label="良好" value="good"/><el-option label="中等" value="medium"/><el-option label="较差" value="poor"/></el-select></label></div></el-card>
<el-card v-if="active==='commissioning' && mode==='service'"><template #header>报告下载</template><p>可下载设计计算、竖井安全或验收运维报告；请先核实相应输入，验收示例数据为合成值。</p><el-button @click="downloadReport('design')">设计计算报告</el-button><el-button @click="downloadReport('shaft')">竖井安全报告</el-button><el-button @click="downloadReport('commissioning')">验收运维手册</el-button></el-card>
<el-alert v-if="active==='commissioning' && mode==='browser'" title="浏览器模式不支持 DOCX 报告，请切换本机服务或命令行。" type="info" :closable="false"/>
<el-card v-if="active!=='sweep' && active!=='household'"><template #header>算例编辑与导入导出</template><el-input v-model="editor" type="textarea" :rows="12"/><div class="actions"><el-button @click="applyEditor">应用编辑</el-button><el-button @click="exportCase('json')">导出 JSON</el-button><el-button @click="exportCase('yaml')">导出 YAML</el-button><label class="file">导入 JSON/YAML<input type="file" accept=".json,.yaml,.yml" @change="importCase"></label><el-button v-if="active!=='commissioning'" type="primary" :loading="busy" @click="calculate">计算</el-button><el-button v-if="mode==='service' && (active==='ventilation'||active==='dwelling')" @click="downloadReport('design')">下载设计报告</el-button><el-button v-if="active==='dwelling'" :loading="busy" @click="calculateInverse">反算最小补风</el-button></div><p v-if="active==='dwelling'">反算使用封闭厨房及模型默认门缝、过流口，新风送至起居室、补风设厨房；与表单中其他位置和尺寸的前向工况可能不同。</p><p v-for="row in inverseResults" :key="row.n50">n50 {{row.n50}} 次/h：最小机械补风 {{(row.result.mechanical.value*3600).toFixed(2)}} m³/h；自然有效面积 {{(row.result.opening.value*10000).toFixed(2)}} cm²。</p></el-card>
<el-card v-if="result"><template #header>计算结果</template><p>{{sourceText}}</p><el-collapse><el-collapse-item title="逐项参数来源分级"><el-table :data="sourceRows"><el-table-column prop="parameter" label="参数"/><el-table-column prop="value" label="输入值"/><el-table-column prop="source" label="来源分级"/></el-table></el-collapse-item></el-collapse><p>软件版本：{{result.provenance?.software_version}}；代码提交：{{result.provenance?.git_commit}}</p><div v-if="active==='ventilation' && current.module==='co2'"><p>二氧化碳法所需风量：{{(result.flow_m3_s*3600).toFixed(2)}} m³/h。</p></div><div v-if="active==='ventilation' && current.module==='ventrate'"><p>全户设计风量：{{(result.design*3600).toFixed(2)}} m³/h；风机风量：{{(result.fan*3600).toFixed(2)}} m³/h；卧室与起居室汇总及全户方法取大值。</p><el-table :data="result.bedrooms"><el-table-column label="卧室"><template #default="s">{{s.$index+1}}</template></el-table-column><el-table-column v-for="key in ['A','B','C','D','selected']" :key="key" :label="key"><template #default="s">{{s.row[key]==null?'—':(s.row[key]*3600).toFixed(2)}}</template></el-table-column></el-table><p>风量单位：m³/h；A 换气次数、B 人员、C 二氧化碳、D 甲醛，selected 为取大值。</p><section v-if="result.noise"><h3>卧室噪声初筛</h3><p v-for="(row,i) in result.noise.settings" :key="i">风量 {{(row.flow_m3_s*3600).toFixed(1)}} m³/h：{{row.a_weighted_db.toFixed(1)}} dB(A)，{{result.noise.checks[i].passed?'未超过':'超过'}}睡眠空间设备声限值 33 dB(A)。</p><p>目标声级下的最大风量：{{(result.noise.maximum_flow_m3_s*3600).toFixed(1)}} m³/h。{{result.noise.source_note}}</p></section><ul><li v-for="(c,i) in result.checks" :key="i">{{c.explanation}}（{{c.strength}}）：{{c.passed?'满足':'不满足'}}</li></ul></div>
<div v-if="active==='dwelling'"><div v-for="(items,n) in result.scenarios" :key="n"><h3>气密性 {{n}} 次/h</h3><div v-for="(x,name) in items" :key="name"><p>方案 {{scenarioNames[name] || '其他方案'}}：厨房压力 {{x.pressures_pa.kitchen.toFixed(2)}} Pa；补风口 {{(x.opening_m3_s*3600).toFixed(2)}} m³/h；户门开启力 {{x.entrance_opening_force_n.toFixed(2)}} N；{{x.negative_pressure_warning?'超过提示阈值':'未触发提示阈值'}}</p><p v-if="x.makeup_location_warning">{{x.makeup_location_warning}}</p><p v-for="(pressure,room) in x.pressures_pa" :key="room">{{roomNames[room] || '房间'}}压力：{{pressure.toFixed(2)}} Pa；{{pressure < -x.threshold_pa ? '超过提示阈值' : '未触发提示'}}</p><p v-for="(door,room) in x.doors" :key="room">{{roomNames[room] || '房间'}}门两侧压差 {{door.delta_p_pa.toFixed(2)}} Pa</p></div></div></div>
<div v-if="active==='shaft'"><div ref="chartEl" class="chart"></div><p>底层300 m³/h：{{result.bottom_meets_300===null?'未运行，不判定':result.bottom_meets_300?'达到':'未达到'}}</p><el-table :data="result.floors"><el-table-column prop="floor" label="楼层"/><el-table-column label="排风量 m³/h"><template #default="s">{{(s.row.exhaust_m3_s*3600).toFixed(2)}}</template></el-table-column><el-table-column prop="shaft_to_outdoor_pa" label="相对室外 Pa"/><el-table-column prop="shaft_to_home_pa" label="相对住户 Pa"/><el-table-column label="倒灌 m³/h"><template #default="s">{{(s.row.backflow_m3_s*3600).toFixed(2)}}</template></el-table-column></el-table></div></el-card>
</main></template>
<style>body{font-family:system-ui,sans-serif;background:#f2f5f7;margin:0;color:#24323b}main{max-width:1200px;margin:auto;padding:24px}header{padding:12px 0}.el-card{margin:16px 0}.grid{display:flex;flex-wrap:wrap;gap:18px;align-items:end}.grid label{display:flex;flex-direction:column;gap:6px}.grid .el-select{width:150px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}.file input{width:150px}.chart{height:360px}</style>
